import{j as e,L as a,b as s,a9 as o,aa as n}from"./index-BpFIgp36.js";const r=[{h:"1 · What LocalTask is",b:'LocalTask is a task platform operated by Local Group ("we", "us"). We match verified, US-based independent contractors ("freelancers") with structured tasks commissioned by vetted cross-border businesses. We coordinate the work and the payment flow; we are not your employer.'},{h:"2 · Independent contractor relationship",b:"You work task by task as an independent contractor. Nothing here creates employment, agency or partnership. You have no obligation to accept any offer, and we have no obligation to send you any particular volume of offers. You are responsible for your own taxes."},{h:"3 · Eligibility & verification",b:"You must be at least 18 years old, US-based, and complete identity verification (KYC) truthfully. Accounts based on false, borrowed or synthetic identities are terminated, and related task history may be voided."},{h:"4 · Tasks, scope and acceptance",b:"Every task offer states its scope, acceptance criteria and USD amount before you accept. Accepting an offer is agreeing to that written scope. Work is reviewed against the stated criteria; submissions may be returned for fixes. If a task or account is flagged for review, your account manager will contact you and the formal review process applies."},{h:"5 · Payment",b:"Tasks are denominated in USD and paid via the payout method you keep on file (stablecoin or digital payment account). Payment details are snapshotted when you accept a task. A task is closed only after you confirm receipt of the payment — until you confirm, it remains open."},{h:"6 · No fees",b:'We never charge freelancers. We will never ask you for deposits, fees, equipment purchases or "training kits". Any such request is fraudulent and does not come from us — report it to support immediately.'},{h:"7 · Account rules",b:"One account per person, in your own legal name. Do not share credentials, misrepresent your identity, or use the platform for anything unlawful. We may suspend or terminate accounts that break these rules or put the network at risk; where money is owed to you for completed and confirmed work, it remains owed."},{h:"8 · Communication",b:"Task coordination happens with your assigned account manager on WhatsApp, Telegram or X. In-app notices are reminders, not a replacement for that direct line."},{h:"9 · Changes",b:"We may update these terms as the platform evolves. Material changes will be reflected on this page with a new date. Continuing to use LocalTask after a change means you accept the updated terms."},{h:"10 · Contact",b:`Questions about these terms: Telegram @${o.telegram}. A person answers.`}];function c(){return e.jsxs("div",{className:"min-h-screen bg-paper text-ink",children:[e.jsx("header",{className:"border-b border-hair",children:e.jsxs("div",{className:"mx-auto flex max-w-3xl items-center justify-between px-5 py-4",children:[e.jsxs(a,{to:"/",className:"flex items-center gap-2.5 font-display text-lg font-medium tracking-tight",children:[e.jsx(s,{className:"h-6 w-6 rounded-md"}),"LocalTask"]}),e.jsx(a,{to:"/",className:"font-mono text-[11px] uppercase tracking-[0.16em] text-muted transition hover:text-ink",children:"← Back"})]})}),e.jsxs("main",{className:"mx-auto max-w-3xl px-5 py-16",children:[e.jsx("p",{className:"font-mono text-[11px] uppercase tracking-[0.28em] text-faint",children:"Terms of Service"}),e.jsx("h1",{className:"mt-3 font-display text-4xl font-medium tracking-tight",children:"The rules, written down."}),e.jsx("p",{className:"mt-3 font-mono text-xs text-faint",children:"Last updated · July 2026"}),e.jsx("div",{className:"mt-10",children:r.map(t=>e.jsxs("section",{className:"border-t border-hair py-6 last:border-b",children:[e.jsx("h2",{className:"font-display text-lg font-medium tracking-tight",children:t.h}),e.jsx("p",{className:"mt-2 text-sm leading-relaxed text-muted",children:t.b})]},t.h))})]}),e.jsx(n,{})]})}export{c as default};
